CREATE TABLE `domains` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `user_id` BIGINT UNSIGNED NOT NULL, `domain` VARCHAR(253) NOT NULL, `cname` VARCHAR(253) NOT NULL, `access_type` TINYINT NOT NULL, `status` TINYINT NOT NULL DEFAULT 1, `audit_status` TINYINT NOT NULL DEFAULT 1, `audit_remark` VARCHAR(255) NULL, `business_type` VARCHAR(32) NOT NULL DEFAULT 'static', `tags` JSON NULL, `remark` VARCHAR(255) NULL, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `deleted_at` DATETIME NULL, PRIMARY KEY (`id`), UNIQUE KEY `domains_domain_key` (`domain`), KEY `domains_user_id_idx` (`user_id`), KEY `domains_status_idx` (`status`), KEY `domains_audit_status_idx` (`audit_status`), KEY `domains_created_at_idx` (`created_at`), CONSTRAINT `domains_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `certificates` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `user_id` BIGINT UNSIGNED NOT NULL, `name` VARCHAR(128) NOT NULL, `cert_type` VARCHAR(32) NOT NULL DEFAULT 'manual', `cert_pem` TEXT NOT NULL, `key_pem` TEXT NOT NULL, `issuer` VARCHAR(512) NOT NULL, `not_before` DATETIME NOT NULL, `not_after` DATETIME NOT NULL, `auto_renew` BOOLEAN NOT NULL DEFAULT false, `status` TINYINT NOT NULL DEFAULT 1, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `certificates_user_id_idx` (`user_id`), KEY `certificates_status_idx` (`status`), CONSTRAINT `certificates_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `domain_configs` (`domain_id` BIGINT UNSIGNED NOT NULL, `default_ttl` INTEGER NOT NULL DEFAULT 3600, `origin_protocol` VARCHAR(16) NOT NULL DEFAULT 'http', `origin_host` VARCHAR(253) NULL, `https_enabled` BOOLEAN NOT NULL DEFAULT false, `cert_id` BIGINT UNSIGNED NULL, `force_https` BOOLEAN NOT NULL DEFAULT false, `hsts_enabled` BOOLEAN NOT NULL DEFAULT false, `hsts_max_age` INTEGER NOT NULL DEFAULT 31536000, `tls_version` VARCHAR(16) NOT NULL DEFAULT 'TLSv1.2', `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`domain_id`), KEY `domain_configs_cert_id_idx` (`cert_id`), CONSTRAINT `domain_configs_domain_id_fkey` FOREIGN KEY (`domain_id`) REFERENCES `domains` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `domain_configs_cert_id_fkey` FOREIGN KEY (`cert_id`) REFERENCES `certificates` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `cache_rules` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `domain_id` BIGINT UNSIGNED NOT NULL, `name` VARCHAR(64) NOT NULL, `priority` INTEGER NOT NULL DEFAULT 0, `match_type` VARCHAR(32) NOT NULL DEFAULT 'path', `match_value` VARCHAR(1024) NOT NULL, `match_mode` VARCHAR(32) NOT NULL DEFAULT 'exact', `action` VARCHAR(32) NOT NULL DEFAULT 'cache', `ttl` INTEGER NOT NULL DEFAULT 3600, `ignore_params` BOOLEAN NOT NULL DEFAULT true, `cache_key` VARCHAR(512) NULL, `status` TINYINT NOT NULL DEFAULT 1, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `cache_rules_domain_id_priority_idx` (`domain_id`,`priority`), CONSTRAINT `cache_rules_domain_id_fkey` FOREIGN KEY (`domain_id`) REFERENCES `domains` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `origin_groups` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `domain_id` BIGINT UNSIGNED NOT NULL, `name` VARCHAR(64) NOT NULL, `lb_policy` VARCHAR(32) NOT NULL DEFAULT 'round_robin', `health_check` JSON NULL, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `origin_groups_domain_id_idx` (`domain_id`), CONSTRAINT `origin_groups_domain_id_fkey` FOREIGN KEY (`domain_id`) REFERENCES `domains` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `origins` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `origin_group_id` BIGINT UNSIGNED NOT NULL, `address` VARCHAR(253) NOT NULL, `port` INTEGER NOT NULL DEFAULT 80, `weight` INTEGER NOT NULL DEFAULT 1, `protocol` VARCHAR(16) NOT NULL DEFAULT 'http', `host` VARCHAR(253) NULL, `status` TINYINT NOT NULL DEFAULT 1, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `origins_origin_group_id_idx` (`origin_group_id`), CONSTRAINT `origins_origin_group_id_fkey` FOREIGN KEY (`origin_group_id`) REFERENCES `origin_groups` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
